// Thin wrapper over the generated Wails bindings (frontend/bindings is generated by
// `wails3 generate bindings`, which `task build` and `task check` run first).
// Components import from here, never from the bindings directly, so the long
// generated path lives in one place and the rest of the app can be tested with a fake.
import { Events } from '@wailsio/runtime'
import { DocsService } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/docs'
import type {
  ChangeSet,
  ScanResult,
  SourceFile,
} from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/docs'
import { ShellService } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/shell'
import type {
  ConfigPatch,
  RootCheck,
} from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/shell'
import type { Settings } from '../../bindings/github.com/wmfarooqi05/folio-ticket-viewer-wails-svelte/internal/settings'

export type { ChangeSet, ConfigPatch, RootCheck, ScanResult, SourceFile }
export type Config = Settings
export type Theme = 'system' | 'light' | 'dark'

/** Files per ReadBatch call: one IPC round trip per chunk. */
const BATCH_SIZE = 100

// ---- shell ----------------------------------------------------------------

export const getConfig = (): Promise<Config> => ShellService.GetConfig()
export const setConfig = (patch: ConfigPatch): Promise<Config> => ShellService.SetConfig(patch)
export const pickFolder = (): Promise<string> => ShellService.PickFolder()
export const checkRoot = (abs: string): Promise<RootCheck> => ShellService.CheckRoot(abs)
export const checkDocs = (repoRoot: string, docsDir: string, roots: string[]): Promise<RootCheck> =>
  ShellService.CheckDocs(repoRoot, docsDir, roots)
export const openExternal = (url: string): Promise<void> => ShellService.OpenExternal(url)
export const openSettingsFile = (): Promise<void> => ShellService.OpenSettingsFile()
export const openInVSCode = (path: string, line = 0): Promise<void> => ShellService.OpenInVSCode(path, line)

// ---- docs -----------------------------------------------------------------

export const scan = (): Promise<ScanResult> => DocsService.Scan()
/** Forgets what was delivered and lists every file as changed (after a root change). */
export const rescan = (): Promise<ScanResult> => DocsService.Rescan()
export const readFile = (path: string): Promise<string> => DocsService.ReadFile(path)
/** The cached index (parsed JSON), or null on a cold start. Also loads Go's stamps. */
export const loadCache = (parserVersion: string): Promise<unknown> => DocsService.LoadCache(parserVersion)
/** Writes the index through Go, which adds its stamps and saves atomically. */
export const saveCache = (parserVersion: string, index: unknown): Promise<void> => DocsService.SaveCache(parserVersion, index)
/** Writes a timing line to the Go log. */
export const logTimings = (line: string): Promise<void> => DocsService.LogTimings(line)
/** One ReadBatch call. The caller keeps batches to BATCH_SIZE paths. */
export const readBatch = async (paths: string[]): Promise<{ files: SourceFile[]; missing: string[] }> => {
  const res = await DocsService.ReadBatch(paths)
  return { files: res.files ?? [], missing: res.missing ?? [] }
}

/** Reads the paths in chunks. Files deleted since the scan come back in `missing`. */
export async function readAll(paths: string[]): Promise<{ files: SourceFile[]; missing: string[] }> {
  const files: SourceFile[] = []
  const missing: string[] = []
  for (let i = 0; i < paths.length; i += BATCH_SIZE) {
    const res = await DocsService.ReadBatch(paths.slice(i, i + BATCH_SIZE))
    files.push(...(res.files ?? []))
    missing.push(...(res.missing ?? []))
  }
  return { files, missing }
}

/** Subscribes to the debounced `docs:changed` event. Returns an unsubscribe function. */
export function onDocsChanged(handler: (cs: ChangeSet) => void): () => void {
  return Events.On('docs:changed', (e) => handler(e.data as ChangeSet))
}
